  '{"status":"incomplete","summary":"The three patterns are compatible through imports. Bind mail=cfh:a:86x82 and bank=cfh:a:mv49j. Sanitize reader outputs before calling the matcher: retain subject/sender/received_at for headers and merchant_name/amount/date for transactions, while blanking name and category_primary. This makes the existing matcher deterministic over only subject, sender, and merchant name. Preserve both readers\u2019 pending/error states in the page. A unique unused slug was not verifiable in this research call.","inputs":[{"name":"mail","token":"cfh:a:86x82","purpose":"Gmail SQLite handle consumed by the monthly email-header reader."},{"name":"bank","token":"cfh:a:mv49j","purpose":"Plaid SQLite handle consumed by the monthly transaction reader."}],"rules":[{"rule":"Import the three published patterns using their exact cf:pattern import hints; reader outputs and matcher inputs must use matching field names.","sourceIds":["pattern-metadata:bfd4f4955e45ff5f","pattern-metadata:3b54171e131d2311","pattern-metadata:f00ba582ee379780","documentation:486f9185e03db344"]},{"rule":"The email reader requires {mail, month?, limit?} and returns headers, headerCount, pending, and errorMessage.","sourceIds":["pattern-metadata:bfd4f4955e45ff5f","pattern-source:0af135442e59a56f"]},{"rule":"The bank reader requires {bank, month?} and returns rows, rowCount, pending, and errorMessage.","sourceIds":["pattern-metadata:3b54171e131d2311","pattern-source:48fdc1db4fe3e304"]},{"rule":"The matcher accepts headers and transactions and returns paid, unpaid, unmatchedPayments, and their counts.","sourceIds":["pattern-metadata:f00ba582ee379780","pattern-source:06d4e18ba44f7855"]},{"rule":"Blank transaction name and category_primary before matching; the published matcher otherwise uses those fields in addition to merchant_name.","sourceIds":["pattern-source:06d4e18ba44f7855"]},{"rule":"Do not pass message bodies or raw transaction data to any model; this composition performs local deterministic text matching.","sourceIds":["pattern-source:06d4e18ba44f7855"]}],"sourceIds":["pattern-metadata:bfd4f4955e45ff5f","pattern-metadata:3b54171e131d2311","pattern-metadata:f00ba582ee379780","pattern-source:0af135442e59a56f","pattern-source:48fdc1db4fe3e304","pattern-source:06d4e18ba44f7855","documentation:486f9185e03db344","documentation:f76f3662a91be9a2","documentation:dccde10b0b51d899"],"missing":["A verified unused slug; choose a candidate during authoring and retry with another slug if publication reports a collision."],"selectedPatternIds":["-xx1hxtvAbY7AL6FeYuQWuEzbC0nOpUOHgXseIac2_w","v6_KSFHs9AmTg9PKwMmPdZyEHxZ9Oykhno4HBOfUo5s","d_z9mtdCBUwBpG0A6nBwOy5_2fxqySuk2zNxeIdXAYA"],"leads":[],"questions":[],"example":{"kind":"pattern-source","content":"import { computed, NAME, pattern, UI, type SqliteDb, type VNode } from \\"commonfabric\\";\\nimport ReadHeaders from \\"cf:pattern:-xx1hxtvAbY7AL6FeYuQWuEzbC0nOpUOHgXseIac2_w\\";\\nimport ReadTransactions from \\"cf:pattern:v6_KSFHs9AmTg9PKwMmPdZyEHxZ9Oykhno4HBOfUo5s\\";\\nimport MatchBills from \\"cf:pattern:d_z9mtdCBUwBpG0A6nBwOy5_2fxqySuk2zNxeIdXAYA\\";\\n\\ninterface Input { mail: SqliteDb; bank: SqliteDb; }\\nexport interface Output {\\n  [NAME]: string;\\n  [UI]: VNode;\\n  pending: boolean;\\n  errorMessage: string;\\n  paidCount: number;\\n  unpaidCount: number;\\n  unmatchedCount: number;\\n}\\n\\nexport default pattern<Input, Output>(({ mail, bank }) => {\\n  const emails = ReadHeaders({ mail, limit: 200 });\\n  const payments = ReadTransactions({ bank });\\n  const headers = computed(() => emails.headers.map((row) => ({\\n    subject: row.subject,\\n    sender: row.sender,\\n    received_at: row.received_at,\\n  })));\\n  const transactions = computed(() => payments.rows.map((row) => ({\\n    merchant_name: row.merchant_name,\\n    amount: row.amount,\\n    date: row.date,\\n    name: \\"\\",\\n    category_primary: \\"\\",\\n  })));\\n  const matched = MatchBills({ headers, transactions });\\n  const pending = computed(() => emails.pending || payments.pending);\\n  const errorMessage = computed(() => [emails.errorMessage, payments.errorMessage]\\n    .filter((message) => message !== \\"\\").join(\\"; \\"));\\n\\n  return {\\n    [NAME]: computed(() => `Bills this month (${matched.unpaidCount} unpaid)`),\\n    pending,\\n    errorMessage,\\n    paidCount: matched.paidCount,\\n    unpaidCount: matched.unpaidCount,\\n    unmatchedCount: matched.unmatchedCount,\\n    [UI]: <cf-vstack gap=\\"4\\" padding=\\"3\\">\\n      <cf-heading level={5}>Bills this month</cf-heading>\\n      {pending ? <cf-text>Loading\u2026</cf-text> : null}\\n      {errorMessage ? <cf-alert status=\\"error\\">{errorMessage}</cf-alert> : null}\\n      <cf-heading level={6}>Paid ({matched.paidCount})</cf-heading>\\n      {matched.paid.map((row) => <cf-text>{row.subject} \u2014 {row.merchant}</cf-text>)}\\n      <cf-heading level={6}>Unpaid ({matched.unpaidCount})</cf-heading>\\n      {matched.unpaid.map((row) => <cf-text>{row.subject} \u2014 {row.sender}</cf-text>)}\\n      <cf-heading level={6}>Unmatched payments ({matched.unmatchedCount})</cf-heading>\\n      {matched.unmatchedPayments.map((row) => <cf-text>{row.merchant} \u2014 {row.amount} \u2014 {row.date}</cf-text>)}\\n    </cf-vstack>,\\n  };\\n});\\n","sourceIds":["pattern-source:0af135442e59a56f","pattern-source:48fdc1db4fe3e304","pattern-source:06d4e18ba44f7855","documentation:486f9185e03db344","documentation:f76f3662a91be9a2"]}';

